INSERT INTO tarot_decks (id, slug, name_en, name_vi, artist, unlock_tier, credit_cost, card_count, description_en, description_vi, cover_image_url, is_active)
VALUES
('ED-01', 'rider-waite-1909', 'Rider-Waite 1909 Restoration', 'Phục chế Rider-Waite 1909', 'Pamela Colman Smith & A.E. Waite', 'FREE', 0, 78, 'The canonical 1909 classic edition restored with antique archival colors.', 'Bản phục chế chuẩn xác ấn bản cổ điển năm 1909 với màu giấy ngà hoài niệm.', '/decks/rider-waite-1909/cards/00_the_fool.webp', true),
('ED-02', 'golden-art-nouveau', 'Golden Art Nouveau Folio', 'Bản dát vàng Art Nouveau', 'Giulia F. Massaglia', 'PRO', 50, 78, 'Lavish gold foil details and flowing organic floral motifs inspired by the Belle Époque.', 'Họa tiết hoa lá uốn lượn và chi tiết ánh kim sang trọng lấy cảm hứng từ thời kỳ hoàng kim.', '/decks/golden-art-nouveau/cover.webp', true),
('ED-03', 'minimalist-charcoal', 'Minimalist Charcoal Noir', 'Than chì Đen tối giản', 'Atelier Monochrome', 'PRO', 40, 78, 'Stripped down brutalist ink sketches emphasizing visceral raw archetypes.', 'Nét vẽ mực than chì tối giản, lược bỏ chi tiết rườm rà tập trung vào năng lượng cốt lõi.', '/decks/minimalist-charcoal/cover.webp', true),
('ED-04', 'botanical-herbarium', 'Botanical Flora Herbarium', 'Thảo mộc Cổ điển Herbarium', 'Sylvia Vance', 'PRO', 40, 78, 'Deep connection between plant folklore, medicinal herbs, and ancient Tarot wisdom.', 'Sự kết hợp giữa tri thức thảo mộc, hoa cỏ cổ truyền và hệ thống biểu tượng Tarot.', '/decks/botanical-herbarium/cover.webp', true),
('ED-05', 'celestial-starlight', 'Celestial Starlight Astral', 'Tinh tú Vũ trụ Celestial', 'Orion Constellation Guild', 'PRO', 60, 78, 'Deep indigo cosmic nebula backdrops with glowing stellar constellations and sacred geometry.', 'Nền vũ trụ chòm sao màu chàm huyền ảo với hình học thiêng liêng rực rỡ.', '/decks/celestial-starlight/cover.webp', true)
INSERT INTO spread_templates (id, code, name_en, name_vi, card_count, crystal_cost, description_en, description_vi, positions_json)
VALUES
('S-01', 'daily_single', 'Daily Guidance Card', 'Lá bài Định hướng Ngày', 1, 0, 'A single card drawn for morning focus, meditation, and daily energetic forecast.', 'Một lá bài duy nhất cho năng lượng ngày mới, lời khuyên và thông điệp tĩnh tâm.', '[{"index":0,"name_en":"Daily Focus & Advice","name_vi":"Năng lượng & Lời khuyên trọng tâm"}]'),
('S-02', 'past_present_future', 'Three Card Timeline', 'Dòng thời gian Quá khứ - Hiện tại - Tương lai', 3, 5, 'The classic three-card layout uncovering origins, current dynamics, and emerging outcomes.', 'Trải bài kinh điển khai mở căn nguyên quá khứ, hiện trạng cốt lõi và hướng đi tương lai.', '[{"index":0,"name_en":"Past Roots","name_vi":"Nguồn gốc Quá khứ"},{"index":1,"name_en":"Present Dynamics","name_vi":"Năng lượng Hiện tại"},{"index":2,"name_en":"Future Outcome","name_vi":"Xu hướng Tương lai"}]'),
('S-03', 'mind_body_spirit', 'Mind, Body & Spirit', 'Thân - Tâm - Trí', 3, 5, 'A holistic diagnostic spread assessing mental clarity, physical stamina, and soul alignment.', 'Chẩn đoán toàn diện về tâm trí, cảm xúc cơ thể và định hướng tâm linh cá nhân.', '[{"index":0,"name_en":"Mind (Mental State)","name_vi":"Tâm trí (Suy nghĩ & Định hướng)"},{"index":1,"name_en":"Body (Action & Grounding)","name_vi":"Thân thể (Hành động & Thể chất)"},{"index":2,"name_en":"Spirit (Higher Intuition)","name_vi":"Linh hồn (Trực giác & Bình an)"}]'),
('S-04', 'relationship_mirror', 'Relationship Mirror', 'Gương phản chiếu Mối quan hệ', 5, 10, 'Five-card deep dive exploring interpersonal connection, unspoken tensions, and shared growth.', 'Trải 5 lá đi sâu vào kết nối hai phía, những điểm nghẽn ngầm và hướng phát triển chung.', '[{"index":0,"name_en":"Your Energy","name_vi":"Năng lượng của bạn"},{"index":1,"name_en":"Their Energy","name_vi":"Năng lượng đối phương"},{"index":2,"name_en":"The Bridge / Tension","name_vi":"Cầu nối / Điểm nghẽn"},{"index":3,"name_en":"Unspoken Factor","name_vi":"Yếu tố tiềm ẩn"},{"index":4,"name_en":"Probable Outcome","name_vi":"Tiềm năng phát triển"}]'),
('S-05', 'celtic_cross', 'The Grand Celtic Cross', 'Thập tự Celtic Toàn diện', 10, 15, 'The legendary ten-card comprehensive examination of life path, hidden obstacles, and destiny.', 'Trải bài cổ điển 10 lá huyền thoại phân tích sâu sắc cục diện cuộc sống, trở ngại ẩn và kết quả.', '[{"index":0,"name_en":"The Heart","name_vi":"Trọng tâm hiện tại"},{"index":1,"name_en":"The Cross (Challenge)","name_vi":"Thách thức cản trở"},{"index":2,"name_en":"The Root (Subconscious)","name_vi":"Cội rễ tiềm thức"},{"index":3,"name_en":"The Past","name_vi":"Quá khứ vừa qua"},{"index":4,"name_en":"The Crown (Aspiration)","name_vi":"Mục tiêu hướng tới"},{"index":5,"name_en":"The Near Future","name_vi":"Tương lai gần"},{"index":6,"name_en":"Self Attitude","name_vi":"Thái độ bản thân"},{"index":7,"name_en":"Environment & Others","name_vi":"Môi trường xung quanh"},{"index":8,"name_en":"Hopes and Fears","name_vi":"Hy vọng & Lo âu"},{"index":9,"name_en":"Final Outcome","name_vi":"Kết quả tổng hợp"}]')
INSERT INTO tarot_cards (id, code, arcana, suit, number, name_en, name_vi, element, keywords_upright_en, keywords_upright_vi, keywords_reversed_en, keywords_reversed_vi, summary_en, summary_vi, image_slug)
VALUES
(0, '00_the_fool', 'MAJOR', NULL, 0, 'The Fool', 'Kẻ Khờ', 'Air', 'New beginnings, innocence, spontaneity, leap of faith', 'Khởi đầu mới, ngây thơ, phiêu lưu, bước nhảy niềm tin', 'Recklessness, risk-taking, hesitation, poor judgment', 'Liều lĩnh vô ích, sợ hãi bước tới, phán đoán non nớt', 'The leap into the unknown with pure trust and child-like wonder.', 'Bước chân vào hành trình mới với tâm hồn thuần khiết và niềm tin tuyệt đối.', '00_the_fool.webp'),
(1, '01_the_magician', 'MAJOR', NULL, 1, 'The Magician', 'Nhà Ảo Thuật', 'Air', 'Manifestation, resourcefulness, power, inspired action', 'Hiện thực hóa, chủ động, hội tụ nguồn lực, sức mạnh ý chí', 'Manipulation, untapped talent, illusion, trickery', 'Thao túng, tiềm năng ngủ quên, ảo vọng', 'Mastery over the four elements to turn will into tangible reality.', 'Làm chủ tứ đại nguyên tố để biến ý niệm thành hiện thực.', '01_the_magician.webp'),
(2, '02_the_high_priestess', 'MAJOR', NULL, 2, 'The High Priestess', 'Nữ Đại Tư Tế', 'Water', 'Intuition, sacred knowledge, divine feminine, subconscious', 'Trực giác, tri thức nội tâm, tĩnh lặng, tâm linh nữ tính', 'Secrets, repressed feelings, surface focus, mistrust', 'Bí mật che giấu, ngắt kết nối trực giác, phân tâm bề nổi', 'Keeper of mysteries between light and dark pillars.', 'Người nắm giữ cánh cổng huyền bí giữa hai trụ ánh sáng và bóng tối.', '02_the_high_priestess.webp'),
(3, '03_the_empress', 'MAJOR', NULL, 3, 'The Empress', 'Hoàng Hậu', 'Earth', 'Abundance, fertility, nurturing, creativity, mother earth', 'Trù phú, nuôi dưỡng, sáng tạo, tình mẫu tử, hòa hợp tự nhiên', 'Creative block, dependence, smothering, burnout', 'Cạn kiệt sáng tạo, kiểm soát thái quá, phụ thuộc cảm xúc', 'The flourishing garden of maternal care and radiant creation.', 'Khu vườn sinh sôi của sự sống, cái đẹp và tình yêu thương.', '03_the_empress.webp'),
(4, '04_the_emperor', 'MAJOR', NULL, 4, 'The Emperor', 'Hoàng Đế', 'Fire', 'Authority, structure, stability, father figure, discipline', 'Trật tự, quyền uy, kỷ luật, bảo vệ, nền tảng vững chắc', 'Tyranny, rigidity, loss of control, cold detachment', 'Độc đoán, cứng nhắc, mất kiểm soát, gia trưởng', 'The pillar of order and benevolent protection establishing secure borders.', 'Trụ cột của kỷ cương và sự vững vàng kiến tạo nền móng cuộc sống.', '04_the_emperor.webp'),
(5, '05_the_hierophant', 'MAJOR', NULL, 5, 'The Hierophant', 'Giáo Hoàng', 'Earth', 'Spiritual wisdom, tradition, mentorship, shared values', 'Tri thức truyền thống, hướng đạo, quy chuẩn, niềm tin tập thể', 'Rebellion, dogma, unconventional beliefs, blind following', 'Cổ hủ, giáo điều, nổi loạn phá vỡ rào cản, học hỏi độc lập', 'Bridge connecting earthly seekers to higher ancestral and spiritual rites.', 'Cầu nối giữa người phàm và các giá trị minh triết lâu đời.', '05_the_hierophant.webp'),
(6, '06_the_lovers', 'MAJOR', NULL, 6, 'The Lovers', 'Người Yêu', 'Air', 'Love, harmony, soul connection, moral choices, duality', 'Tình yêu, hòa hợp, gắn kết tâm hồn, lựa chọn đạo đức', 'Disharmony, misalignment of values, indecision', 'Rạn nứt, bất đồng giá trị cốt lõi, trốn tránh lựa chọn', 'The sacred union of dual souls guided by higher celestial grace.', 'Giao hòa thiêng liêng giữa hai tâm hồn dưới sự bảo hộ của thiên thần.', '06_the_lovers.webp'),
(7, '07_the_chariot', 'MAJOR', NULL, 7, 'The Chariot', 'Cỗ Chiến Xa', 'Water', 'Willpower, determination, conquest, triumph over adversity', 'Ý chí sắt đá, quyết tâm, chinh phục, vượt qua nghịch cảnh', 'Lack of direction, aggression, defeat, internal conflicts', 'Mất phương hướng, hiếu thắng mù quáng, xung đột nội tâm', 'Guiding dual opposing forces with sheer discipline toward victory.', 'Điều khiển hai lực lượng đối lập tiến thẳng đến mục tiêu vinh quang.', '07_the_chariot.webp'),
(8, '08_strength', 'MAJOR', NULL, 8, 'Strength', 'Sức Mạnh', 'Fire', 'Inner courage, compassion, patience, gentle mastery', 'Can đảm nội tâm, từ bi, kiên nhẫn, chế ngự nhẹ nhàng', 'Self-doubt, raw fury, vulnerability, exhaustion', 'Tự ti, mất bình tĩnh, cơn thịnh nộ bộc phát, kiệt sức', 'Taming the fierce beast through soft grace and unwavering presence.', 'Chế ngự sư tử hung tợn bằng sự dịu dàng và sức mạnh nội tại tĩnh lặng.', '08_strength.webp'),
(9, '09_the_hermit', 'MAJOR', NULL, 9, 'The Hermit', 'Ẩn Sĩ', 'Earth', 'Soul-searching, introspection, inner guidance, solitude', 'Chiêm nghiệm, soi sáng nội tâm, tĩnh tại, tìm kiếm chân lý', 'Loneliness, isolation, withdrawal from reality, stubbornness', 'Cô lập cực đoan, xa lánh thực tại, bảo thủ từ chối giúp đỡ', 'Carrying the lantern of inner wisdom upon the mountain peak.', 'Thắp sáng ngọn đèn minh triết cô độc trên đỉnh núi cao.', '09_the_hermit.webp'),
(10, '10_wheel_of_fortune', 'MAJOR', NULL, 10, 'Wheel of Fortune', 'Vòng Quay May Mắn', 'Fire', 'Cycles of life, destiny, turning point, luck, evolution', 'Vận mệnh xoay vần, bước ngoặt, cơ duyên, chu kỳ chuyển biến', 'Bad luck, resistance to change, cycle breaking down', 'Vận xui nhất thời, chống cự thay đổi, lặp lại vết xe đổ', 'The eternal spinning wheel reminding us that all conditions are transient.', 'Vòng quay bất tận nhắc nhở vạn vật luôn vận động và thay đổi không ngừng.', '10_wheel_of_fortune.webp'),
(11, '11_justice', 'MAJOR', NULL, 11, 'Justice', 'Công Lý', 'Air', 'Truth, fairness, accountability, karmic balance, clarity', 'Chân lý, công bằng, trách nhiệm, luật nhân quả, minh bạch', 'Injustice, bias, dishonesty, dodging consequences', 'Thiên vị, bất công, trốn tránh trách nhiệm, thông tin sai lệch', 'The balanced scales and double-edged sword discerning pure truth.', 'Cán cân chuẩn xác và thanh gươm phân định rõ chân lý khách quan.', '11_justice.webp'),
(12, '12_the_hanged_man', 'MAJOR', NULL, 12, 'The Hanged Man', 'Người Treo Ngược', 'Water', 'Surrender, new perspective, pause, letting go, sacrifice', 'Buông bỏ chấp niệm, góc nhìn mới, tạm dừng tĩnh tâm, hy sinh vì mục đích cao cả', 'Resistance, stalling, martyr complex, pointless delay', 'Níu kéo vô ích, trì hoãn tiêu cực, đóng vai nạn nhân', 'Suspension between realms that grants transcendent vision.', 'Treo mình giữa hai cõi để đón nhận góc nhìn thức tỉnh khai sáng.', '12_the_hanged_man.webp'),
(13, '13_death', 'MAJOR', NULL, 13, 'Death', 'Cái Chết', 'Water', 'Transformation, end of an era, rebirth, renewal, metamorphosis', 'Chuyển hóa sâu sắc, kết thúc giai đoạn, tái sinh, khởi sắc mới', 'Fear of change, stagnation, lingering attachments', 'Sợ buông tay, trì trệ kìm hãm, níu giữ tàn tích cũ', 'Clearing the dry soil so fresh blossom can sprout in spring.', 'Khép lại cái cũ để mảnh đất màu mỡ đón mầm sống mới đâm chồi.', '13_death.webp'),
(14, '14_temperance', 'MAJOR', NULL, 14, 'Temperance', 'Tiết Độ', 'Fire', 'Balance, moderation, alchemy, patient synthesis, harmony', 'Cân bằng, tiết chế, hòa hợp các thái cực, kiên nhẫn, điềm tĩnh', 'Imbalance, excess, clashing forces, impatience', 'Mất cân bằng, thái quá, vội vã, xung đột các dòng chảy', 'Blending water and essence in perfect steady measure.', 'Rót dòng nước giữa hai bình tạo nên sự cân bằng và chữa lành kỳ diệu.', '14_temperance.webp'),
(15, '15_the_devil', 'MAJOR', NULL, 15, 'The Devil', 'Ác Quỷ', 'Earth', 'Shadow self, addiction, material bondage, illusion of limitation', 'Mặt tối nội tâm, cám dỗ, xiềng xích vô hình, phụ thuộc vật chất', 'Breaking chains, liberation, reclaiming personal power', 'Thức tỉnh thoát khỏi trói buộc, lấy lại tự do và quyền làm chủ', 'Chains worn voluntarily that disappear once awareness returns.', 'Chiếc xiềng xích lỏng lẻo sẽ tự tan biến khi nhận thức được đánh thức.', '15_the_devil.webp'),
(16, '16_the_tower', 'MAJOR', NULL, 16, 'The Tower', 'Tòa Tháp', 'Fire', 'Sudden upheaval, shattering illusions, breakthrough, awakening', 'Đổ vỡ bất ngờ, thức tỉnh đột ngột, phá vỡ ảo tưởng, tái thiết', 'Disaster averted, fear of suffering, delaying the inevitable', 'Cố níu giữ nền tảng rỗng mục, sợ hãi sụp đổ tất yếu', 'The lightning strike that razes false foundations to clear holy ground.', 'Tia sét thanh trừng những bức tường ảo tưởng để trả lại nền đất thật.', '16_the_tower.webp'),
(17, '17_the_star', 'MAJOR', NULL, 17, 'The Star', 'Ngôi Sao', 'Air', 'Hope, faith, inspiration, serene renewal, spiritual healing', 'Hy vọng rực sáng, niềm tin, chữa lành tâm hồn, bình yên sau giông bão', 'Hopelessness, despair, disconnection, lack of inspiration', 'Tuyệt vọng, hoài nghi ánh sáng, mất niềm tin vào tương lai', 'The calm celestial light that guides weary travelers home.', 'Ánh sao dịu êm soi đường dẫn lối người lữ hành tìm lại bình an.', '17_the_star.webp'),
(18, '18_the_moon', 'MAJOR', NULL, 18, 'The Moon', 'Mặt Trăng', 'Water', 'Illusion, subconscious fears, intuition, mystery, shadow realms', 'Ảo ảnh, lo âu tiềm thức, trực giác bí ẩn, màn sương mờ mịt', 'Release of fear, unveiling deception, lucid clarity', 'Sương mù tan dần, sáng tỏ sự thật, đối diện nỗi sợ sâu thẳm', 'Walking the nocturnal trail accompanied by the wolf and dog.', 'Bước đi trên con đường trăng đêm cùng tiếng sói tru và vực sâu tiềm thức.', '18_the_moon.webp'),
(19, '19_the_sun', 'MAJOR', NULL, 19, 'The Sun', 'Mặt Trời', 'Fire', 'Joy, clarity, vitality, success, radiant optimism, celebration', 'Niềm vui rạng rỡ, thành công, sinh lực dồi dào, thấu suốt, hoan ca', 'Temporary gloom, clouded optimism, delayed clarity', 'Đám mây che khuất niềm vui tạm thời, kiêu ngạo thái quá', 'Warm golden brilliance blessing all living things with abundant life.', 'Ánh dương rạng ngời sưởi ấm vạn vật, mang lại sự tự tin và hạnh phúc thuần khiết.', '19_the_sun.webp'),
(20, '20_judgement', 'MAJOR', NULL, 20, 'Judgement', 'Phán Xét', 'Fire', 'Awakening, spiritual calling, rebirth, reckoning, clarity', 'Thức tỉnh, tiếng gọi thiên mệnh, hồi sinh, tha thứ, phán quyết đúng đắn', 'Self-doubt, harsh self-criticism, refusing the call', 'Tự dằn vặt, trốn tránh tiếng gọi nội tâm, phán xét thiển cận', 'The clarion trumpet call rising souls into higher enlightened existence.', 'Tiếng kèn thiên sứ đánh thức tâm hồn bước vào nấc thang nhận thức mới.', '20_judgement.webp'),
(21, '21_the_world', 'MAJOR', NULL, 21, 'The World', 'Thế Giới', 'Earth', 'Completion, wholeness, accomplishment, integration, fulfillment', 'Viên mãn, hoàn thành chu kỳ, hòa hợp trọn vẹn, mở ra chân trời mới', 'Incompletion, lingering loose ends, delayed celebration', 'Chưa trọn vẹn, bỏ dở chặng cuối, chậm trễ chạm tới đích', 'The celebratory victory dance within the celestial laurel wreath.', 'Vũ điệu chiến thắng trong vòng nguyệt quế của một hành trình trọn vẹn.', '21_the_world.webp')
